import{_ as r,a0 as n,w as p,s as c,ao as a,I as d,x as t,a1 as s,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const N=JSON.parse('{"title":"你或许不知道的实用 GNOME Shell 快捷键 | LCTT x X-CMD","titleTemplate":false,"description":"你或许不知道的实用 GNOME Shell 快捷键 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你或许不知道的实用 GNOME Shell 快捷键 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你或许不知道的实用 GNOME Shell 快捷键 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171120 Useful GNOME Shell Keyboard Shortcuts You Might Not Know About","title":"你或许不知道的实用 GNOME Shell 快捷键","tag":"201712","desc":""},"relativePath":"201712/20171120 Useful GNOME Shell Keyboard Shortcuts You Might Not Know About.md","filePath":"[post].md"}'),h={name:"201712/20171120 Useful GNOME Shell Keyboard Shortcuts You Might Not Know About.md"};function u(i,e,m,g,f,S){const o=n("Link");return p(),c("div",null,[e[16]||(e[16]=a('<h1 id="你或许不知道的实用-gnome-shell-快捷键" tabindex="-1">你或许不知道的实用 GNOME Shell 快捷键 <a class="header-anchor" href="#你或许不知道的实用-gnome-shell-快捷键" aria-label="Permalink to “你或许不知道的实用 GNOME Shell 快捷键”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/gnome-shortcuts-00-featured.jpg" alt=""></p><p>由于 Ubuntu 在 17.10 发行版本中转移到了 GNOME Shell，许多用户可能对那些实用的快捷键以及创建自己的快捷键感兴趣。这篇文章就是介绍这两方面的。</p><h3 id="已有的便捷的-gnome-shell-快捷键" tabindex="-1">已有的便捷的 GNOME Shell 快捷键 <a class="header-anchor" href="#已有的便捷的-gnome-shell-快捷键" aria-label="Permalink to “已有的便捷的 GNOME Shell 快捷键”">​</a></h3><p>如果你希望 GNOME 有成百上千种快捷键，你会失望地发现，情况并非如此。快捷键的列表不会太长，而且并不是全部都对你有用，但仍然会有许多快捷键可以用得上的。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/gnome-shortcuts-01-settings.jpg" alt="gnome-shortcuts-01-settings" title="gnome-shortcuts-01-settings"></p><p>可以通过菜单“设置 -&gt; 设备 -&gt; 键盘”访问快捷方式列表。以下是一些不太流行但实用的快捷方式。</p><ul><li><code>Ctrl</code> + <code>Alt</code> + <code>T</code> - 这是一个用来启动终端的快捷键组合，你可以在 GNOME 的任何地方使用它。</li></ul><p>我个人经常使用的两个快捷键是：</p><ul><li><code>Alt</code> + <code>F4</code> - 关闭最顶层端口</li><li><code>Alt</code> + <code>F8</code> - 调整窗口大小</li></ul><p>大多数人都知道如何用 <code>Alt</code> + <code>Tab</code> 在打开的应用程序窗口之间，但是你可能不知道可以使用 <code>Alt</code> + <code>Shift</code> + <code>Tab</code> 在应用程序窗口之间进行反方向切换。</p><p>在切换窗口界面时，另一个有用的组合键是 <code>Alt</code> + <code>~</code> （<code>tab</code> 键上面的一个键）。</p><p>要是你想显示活动概览，你可以用快捷键 <code>Alt</code> + <code>F1</code>。</p><p>有很多跟工作台有关的快捷键。如果你像我那样不经常使用多个工作台的话，这些快捷键对来说是没用的。尽管如此，以下几个快捷键还是值得留意的：</p><ul><li><code>Super</code> + <code>PageUp</code> （或者 <code>PageDown</code> ）移动到上方或下方的工作台</li><li><code>Ctrl</code> + <code>Alt</code> + <code>Left</code> （或 <code>Right</code> ）移动到左侧或右侧的工作台</li></ul><p>如果在这些快捷键中加上 <code>Shift</code> ，例如 <code>Shift</code> + <code>Ctrl</code> + <code>Alt</code> + <code>Left</code>，则可以把当前窗口移动到其他工作区。</p><p>另一个我最喜欢是辅助功能中的调整文字大小的快捷键。你可以用 <code>Ctrl</code> + <code>+</code> （或 <code>Ctrl</code> + <code>-</code> ）快速缩放字体大小。在某些情况下，这个快捷键可能默认是禁用的，所以在尝试之前请先检查一下。</p>',17)),d("p",null,[e[1]||(e[1]=t("上述是一些鲜为人知但是十分实用的键盘快捷键。如果你想知道更多实用的快捷键，可以查看",-1)),s(o,{href:"https://wiki.gnome.org/Projects/GnomeShell/CheatSheet"},{default:l(()=>[...e[0]||(e[0]=[t("官方 GNOME Shell 快捷键列表",-1)])]),_:1}),e[2]||(e[2]=t("。",-1))]),e[17]||(e[17]=a('<h3 id="如何创建自己的-gnome-shell-快捷键" tabindex="-1">如何创建自己的 GNOME Shell 快捷键 <a class="header-anchor" href="#如何创建自己的-gnome-shell-快捷键" aria-label="Permalink to “如何创建自己的 GNOME Shell 快捷键”">​</a></h3><p>如果默认的快捷键不符合您的喜好，可以更改它们或创建新的快捷键。你同样可以通过菜单“设置 -&gt; 设备 -&gt; 键盘“完成这些操作。当你选择想更改的快捷键条目时，下面的对话框就会弹出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/gnome-shortcuts-02-change-shortcut.png" alt="gnome-shortcuts-02-change-shortcut" title="gnome-shortcuts-02-change-shortcut"></p><p>输入你想要的键盘快捷键组合。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/gnome-shortcuts-03-set-shortcut.png" alt="gnome-shortcuts-03-set-shortcut" title="gnome-shortcuts-03-set-shortcut"></p><p>如果这个快捷键已经被使用，你会得到一个消息。如果没有，只需点击设置，就完成了。</p><p>如果要添加新快捷键而不是更改现有快捷键，请向下滚动，直到看到 “+” 标志，单击它，在出现的对话框中输入新键盘快捷键的名称和快捷键组合。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/gnome-shortcuts-04-add-custom-shortcut.png" alt="gnome-shortcuts-04-add-custom-shortcut" title="gnome-shortcuts-04-add-custom-shortcut"></p><p>GNOME 默认情况下并没有提供大量的 shell 快捷键，上面列出的是一些比较实用的快捷键。如果这些快捷键对你来说不够，你可以随时创建自己的快捷键。</p><hr>',10)),d("p",null,[e[4]||(e[4]=t("via: ",-1)),s(o,{href:"https://www.maketecheasier.com/gnome-shell-keyboard-shortcuts/"},{default:l(()=>[...e[3]||(e[3]=[t("https://www.maketecheasier.com/gnome-shell-keyboard-shortcuts/",-1)])]),_:1})]),d("p",null,[e[8]||(e[8]=t("作者：",-1)),s(o,{href:"https://www.maketecheasier.com/author/adaivanoff/"},{default:l(()=>[...e[5]||(e[5]=[t("Ada Ivanova",-1)])]),_:1}),e[9]||(e[9]=t(" 译者：",-1)),s(o,{href:"https://github.com/imquanquan"},{default:l(()=>[...e[6]||(e[6]=[t("imquanquan",-1)])]),_:1}),e[10]||(e[10]=t(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:l(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),d("p",null,[e[13]||(e[13]=t("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原创编译，",-1)),s(o,{href:"https://linux.cn/"},{default:l(()=>[...e[12]||(e[12]=[t("Linux中国",-1)])]),_:1}),e[15]||(e[15]=t(" 荣誉推出",-1))])])}const M=r(h,[["render",u]]);export{N as __pageData,M as default};
